//! The ai-env relay protocol, version 1 (`proto/ai_env/relay/v1/relay.proto`).
//!
//! The bindings under `src/gen` are generated by `tools/relay-protogen` (`make relay-proto`,
//! which needs protoc) and committed, so building this crate never needs protoc. The
//! protocol is generic: a source is a name plus ops with JSON parameters, and no concrete
//! source is ever named here. `prost`, `tonic` and `tonic_prost` are re-exported so that
//! every crate on the tunnel compiles against the same versions.

pub use prost;
pub use tonic;
pub use tonic_prost;

/// The protocol version carried in `Challenge.protocol` and `Hello.protocol`.
pub const PROTOCOL: u32 = 1;

/// The encoded `FileDescriptorSet` of `relay.proto`, for gRPC reflection.
pub const FILE_DESCRIPTOR_SET: &[u8] = include_bytes!("gen/descriptor.bin");

/// The generated messages, clients and servers of `ai_env.relay.v1`.
#[allow(clippy::all, clippy::pedantic, clippy::nursery, missing_docs, unreachable_pub)]
pub mod v1 {
    include!("gen/ai_env.relay.v1.rs");
}

#[cfg(test)]
mod tests {
    use super::v1::{relay_frame, worker_frame, Challenge, Hello, RelayFrame, SigAlg, WorkerFrame};
    use prost::Message;

    #[test]
    fn frames_round_trip_and_keep_their_tags() {
        let frame = RelayFrame { msg: Some(relay_frame::Msg::Challenge(Challenge { nonce: vec![7; 32], relay_id: "relay-test".into(), protocol: super::PROTOCOL })) };
        let bytes = frame.encode_to_vec();
        // Field 1 of RelayFrame (the oneof's `challenge`), length-delimited: tag byte 0x0a.
        assert_eq!(bytes[0], 0x0a, "the Challenge arm keeps tag 1");
        assert_eq!(RelayFrame::decode(bytes.as_slice()).expect("decodes"), frame);

        let hello = WorkerFrame { msg: Some(worker_frame::Msg::Hello(Hello { worker_id: "w1".into(), alg: SigAlg::Ed25519 as i32, public_key: vec![1; 32], protocol: 1, sdk_version: "0.1.0".into() })) };
        let back = WorkerFrame::decode(hello.encode_to_vec().as_slice()).expect("decodes");
        assert_eq!(back, hello);
    }

    #[test]
    fn the_descriptor_set_names_the_package_and_both_services() {
        let set = prost_types_free_scan(super::FILE_DESCRIPTOR_SET);
        for needle in ["ai_env.relay.v1", "WorkerTunnel", "Relay", "ListSources", "Call", "Open"] {
            assert!(set.contains(needle), "the descriptor set names {needle}");
        }
    }

    /// The descriptor's strings, without pulling prost-types into the crate.
    fn prost_types_free_scan(bytes: &[u8]) -> String {
        String::from_utf8_lossy(bytes).into_owned()
    }
}
